const app = getApp()
var commonUtil = require('../../utils/common-util.js')
Page({
  data: {
    notifications: [],
    loading: true
  },

  onLoad: function() {
    this.loadNotifications()
  },

  onShow: function() {
    this.loadNotifications()
    // 更新 profile 页的未读数
    var pages = getCurrentPages()
    for (var i = 0; i < pages.length; i++) {
      if (pages[i].loadUnreadNotifyCount) {
        pages[i].loadUnreadNotifyCount()
        break
      }
    }
  },

  loadNotifications: function() {
    var that = this
    that.setData({ loading: true })
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getSystemNotifications', userInfo: app.globalData.userInfo || {} },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function(n) {
            var d = n.createTime ? new Date(n.createTime) : null
            n.createTimeText = d ? (d.getMonth()+1) + '/' + d.getDate() + ' ' + d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') : ''
            return n
          })
          that.setData({ notifications: list, loading: false })
        } else {
          that.setData({ loading: false })
        }
      },
      fail: function() { that.setData({ loading: false }) }
    })
  },

  readNotification: function(e) {
    var id = e.currentTarget.dataset.id
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'markNotificationRead', _id: id },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          that.loadNotifications()
        }
      }
    })
  },

})
